class Solution {
  public String minWindow(String s1, String s2) {
    int start = -1, bestLen = Integer.MAX_VALUE;
    for (int i = 0, j = 0; i < s1.length(); i++) {
      if (s1.charAt(i) != s2.charAt(j)) continue;
      if (++j < s2.length()) continue;
      // s2 matched ending at i: walk back to the latest start that still matches
      int end = i;
      for (j = s2.length() - 1; j >= 0; i--) if (s1.charAt(i) == s2.charAt(j)) j--;
      i++;
      if (end - i + 1 < bestLen) {
        bestLen = end - i + 1;
        start = i;
      }
      j = 0;
    }
    return start == -1 ? "" : s1.substring(start, start + bestLen);
  }
}
